:root {
  --bg: #0b1220;
  --bg-elevated: #111a2e;
  --bg-card: #162238;
  --bg-muted: #1d2c46;
  --border: rgba(148, 163, 184, 0.18);
  --border-strong: rgba(148, 163, 184, 0.28);
  --text: #e5eefc;
  --text-muted: #9fb1cc;
  --brand: #60a5fa;
  --brand-strong: #3b82f6;
  --success: #34d399;
  --warning: #fbbf24;
  --danger: #f87171;
  --shadow: 0 12px 30px rgba(2, 6, 23, 0.35);
  --radius: 14px;
}

html, body {
  min-height: 100%;
}

body {
  margin: 0;
  background: linear-gradient(180deg, #0b1220 0%, #0f172a 45%, #0b1220 100%);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

a {
  color: var(--brand);
  text-decoration: none;
  transition: color 160ms ease;
}

a:hover {
  color: #93c5fd;
}

button,
[role="button"] {
  transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, color 160ms ease, opacity 160ms ease;
}

button:hover,
[role="button"]:hover {
  transform: translateY(-1px);
}

button:active,
[role="button"]:active {
  transform: translateY(0);
}

button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
a:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}

input,
textarea,
select {
  background-color: #0f172a;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 10px;
  transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease, color 160ms ease;
}

input::placeholder,
textarea::placeholder {
  color: #7b8ca8;
  opacity: 1;
}

input:focus,
textarea:focus,
select:focus {
  border-color: rgba(96, 165, 250, 0.8);
  box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.16);
}

.view-enter {
  animation: fadeIn 180ms ease-out both;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.card,
.panel,
.ticket-row,
.table-shell {
  background-color: rgba(17, 26, 46, 0.88);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.card:hover,
.panel:hover,
.ticket-row:hover {
  border-color: var(--border-strong);
}

.table-shell {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  color: var(--text);
}

th,
td {
  padding: 0.8rem 0.9rem;
  border-bottom: 1px solid rgba(148, 163, 184, 0.14);
  text-align: left;
  vertical-align: middle;
}

th {
  font-size: 0.78rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
  background-color: rgba(15, 23, 42, 0.8);
}

tbody tr {
  transition: background-color 160ms ease;
}

tbody tr:hover {
  background-color: rgba(96, 165, 250, 0.08);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 0.78rem;
  line-height: 1;
}

.badge.brand { background-color: rgba(96, 165, 250, 0.14); color: #bfdbfe; }
.badge.success { background-color: rgba(52, 211, 153, 0.14); color: #a7f3d0; }
.badge.warning { background-color: rgba(251, 191, 36, 0.14); color: #fde68a; }
.badge.danger { background-color: rgba(248, 113, 113, 0.14); color: #fecaca; }

hr {
  border: 0;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
}

.container,
main,
section {
  width: 100%;
  max-width: 100%;
}

img,
svg,
canvas {
  max-width: 100%;
}

#login-view,
#app-view {
  max-width: 100%;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #0b1220;
}

::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.28);
  border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(148, 163, 184, 0.42);
}

(function () {
  const AUTH_KEY = 'app:auth';
  const ENTITIES_KEY = 'app:entities';
  const DEMO_EMAIL = 'demo@example.com';
  const DEMO_PASSWORD = 'demo';

  const sampleEntities = [
    {
      subject: 'Cannot access billing portal',
      customer: 'Ava Johnson',
      channel: 'email',
      status: 'open',
      priority: 'high',
      slaDueInMinutes: 42,
      assignee: 'Mia',
      amount: 49
    },
    {
      subject: 'Chat request about password reset',
      customer: 'Noah Patel',
      channel: 'chat',
      status: 'pending',
      priority: 'medium',
      slaDueInMinutes: 18,
      assignee: 'Liam',
      amount: 49
    },
    {
      subject: 'Refund request after duplicate charge',
      customer: 'Emma Chen',
      channel: 'email',
      status: 'open',
      priority: 'urgent',
      slaDueInMinutes: 7,
      assignee: 'Sophia',
      amount: 49
    },
    {
      subject: 'How to add another team member?',
      customer: 'Oliver Brown',
      channel: 'chat',
      status: 'resolved',
      priority: 'low',
      slaDueInMinutes: 0,
      assignee: 'Mia',
      amount: 49
    }
  ];

  const api = {
    list() {
      try {
        return JSON.parse(localStorage.getItem(ENTITIES_KEY) || '[]');
      } catch {
        return [];
      }
    },
    create(obj) {
      const items = api.list();
      const entity = {
        ...obj,
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString()
      };
      items.push(entity);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(items));
      return entity;
    },
    remove(id) {
      const items = api.list().filter(item => item.id !== id);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(items));
      return items;
    }
  };

  function seedEntities() {
    const existing = api.list();
    if (existing.length === 0) {
      const seeded = sampleEntities.map(item => ({
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        ...item
      }));
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(seeded));
    }
  }

  function qs(sel) {
    return document.querySelector(sel);
  }

  function show(el, visible) {
    if (!el) return;
    el.style.display = visible ? '' : 'none';
  }

  function getAuth() {
    try {
      return JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
    } catch {
      return null;
    }
  }

  function setAuth(email) {
    localStorage.setItem(
      AUTH_KEY,
      JSON.stringify({ email, loggedAt: new Date().toISOString() })
    );
  }

  function clearAuth() {
    localStorage.removeItem(AUTH_KEY);
  }

  function currentStatusCounts(items) {
    return items.reduce((acc, item) => {
      acc.total += 1;
      acc[item.status] = (acc[item.status] || 0) + 1;
      acc.amount += Number(item.amount || 0);
      return acc;
    }, { total: 0, amount: 0, open: 0, pending: 0, resolved: 0 });
  }

  function renderKpis() {
    const strip = qs('#kpi-strip');
    if (!strip) return;

    const items = api.list();
    const counts = currentStatusCounts(items);
    const overdue = items.filter(item => item.status !== 'resolved' && Number(item.slaDueInMinutes || 0) <= 15).length;

    strip.innerHTML = [
      { label: 'Tickets', value: counts.total },
      { label: 'Open', value: counts.open },
      { label: 'Pending', value: counts.pending },
      { label: 'Resolved', value: counts.resolved },
      { label: 'Revenue', value: `$${counts.amount}` },
      { label: 'SLA at risk', value: overdue }
    ].map(kpi => `
      <div class="kpi">
        <div class="kpi-label">${kpi.label}</div>
        <div class="kpi-value">${kpi.value}</div>
      </div>
    `).join('');
  }

  function renderList() {
    const list = qs('#entity-list');
    if (!list) return;

    const items = api.list().sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

    if (items.length === 0) {
      list.innerHTML = '<p>No tickets yet.</p>';
      return;
    }

    list.innerHTML = `
      <table class="entity-table">
        <thead>
          <tr>
            <th>Subject</th>
            <th>Customer</th>
            <th>Channel</th>
            <th>Status</th>
            <th>Priority</th>
            <th>SLA</th>
            <th>Assignee</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          ${items.map(item => {
            const badgeClass = item.status === 'resolved' ? 'ok' : item.status === 'pending' ? 'warn' : 'open';
            const slaText = item.status === 'resolved' ? 'Closed' : `${item.slaDueInMinutes} min`;
            return `
              <tr data-id="${item.id}">
                <td>${item.subject || ''}</td>
                <td>${item.customer || ''}</td>
                <td>${item.channel || ''}</td>
                <td><span class="badge ${badgeClass}">${item.status || ''}</span></td>
                <td>${item.priority || ''}</td>
                <td>${slaText}</td>
                <td>${item.assignee || ''}</td>
                <td><button type="button" data-remove-id="${item.id}">Delete</button></td>
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    `;

    list.querySelectorAll('[data-remove-id]').forEach(btn => {
      btn.addEventListener('click', () => {
        api.remove(btn.getAttribute('data-remove-id'));
        renderList();
        renderKpis();
      });
    });
  }

  function renderAppUser() {
    const auth = getAuth();
    const label = qs('#user-email');
    if (label && auth) label.textContent = auth.email;
  }

  function showApp() {
    show(qs('#login-view'), false);
    show(qs('#app-view'), true);
    renderAppUser();
    renderList();
    renderKpis();
  }

  function showLogin() {
    show(qs('#app-view'), false);
    show(qs('#login-view'), true);
  }

  function bindAuth() {
    const btn = qs('#login-btn');
    const error = qs('#login-error');
    const emailInput = qs('#login-email');
    const passwordInput = qs('#login-password');

    if (btn) {
      btn.addEventListener('click', () => {
        const email = (emailInput && emailInput.value || '').trim();
        const password = (passwordInput && passwordInput.value || '').trim();

        if (email === DEMO_EMAIL && password === DEMO_PASSWORD) {
          if (error) error.textContent = '';
          setAuth(email);
          showApp();
        } else {
          if (error) error.textContent = 'Invalid demo credentials. Try demo@example.com / demo';
        }
      });
    }

    const logout = qs('#logout-btn');
    if (logout) {
      logout.addEventListener('click', () => {
        clearAuth();
        location.reload();
      });
    }
  }

  function bindCreateForm() {
    const form = qs('#create-form');
    if (!form) return;

    form.addEventListener('submit', e => {
      e.preventDefault();
      const data = new FormData(form);
      const entity = {};
      for (const [key, value] of data.entries()) entity[key] = String(value).trim();

      if (!entity.subject) entity.subject = 'Untitled ticket';
      if (!entity.customer) entity.customer = 'Unknown customer';
      if (!entity.status) entity.status = 'open';
      if (!entity.channel) entity.channel = 'email';
      if (!entity.priority) entity.priority = 'medium';
      if (!entity.assignee) entity.assignee = 'Unassigned';
      entity.amount = Number(entity.amount || 49);
      entity.slaDueInMinutes = Number(entity.slaDueInMinutes || 30);

      api.create(entity);
      form.reset();
      renderList();
      renderKpis();
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedEntities();
    bindAuth();
    bindCreateForm();

    if (getAuth()) {
      showApp();
    } else {
      showLogin();
    }
  });
})();

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field
from typing import Any, Dict, List, Optional
from uuid import uuid4
from datetime import datetime, timezone

app = FastAPI(title="Helpdesk & Ticketing API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_EMAIL = "demo@example.com"
DEMO_PASSWORD = "demo"

# In-memory storage for demo/runtime use.
# A real database would be wired in here instead.
entities: Dict[str, Dict[str, Any]] = {}
tokens: Dict[str, Dict[str, Any]] = {}


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class LoginReq(BaseModel):
    email: str
    password: str


class LoginUser(BaseModel):
    id: str
    email: str
    name: str


class LoginRes(BaseModel):
    token: str
    user: LoginUser


class EntityIn(BaseModel):
    title: str = Field(default="")
    amount: float = Field(default=0)
    description: Optional[str] = None
    status: Optional[str] = None
    customer: Optional[str] = None


class EntityOut(EntityIn):
    id: str
    createdAt: str


def auth_user(request: Request) -> LoginUser:
    auth = request.headers.get("authorization", "")
    if not auth.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    token = auth.removeprefix("Bearer ").strip()
    user = tokens.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    return LoginUser(**user)


@app.get("/api/health")
def health() -> Dict[str, str]:
    return {"status": "ok", "version": app.version or "1.0.0"}


@app.post("/api/auth/login", response_model=LoginRes)
def login(req: LoginReq) -> LoginRes:
    if req.email != DEMO_EMAIL or req.password != DEMO_PASSWORD:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")

    user = LoginUser(id="demo-user", email=DEMO_EMAIL, name="Demo User")
    token = uuid4().hex
    tokens[token] = user.model_dump()
    return LoginRes(token=token, user=user)


@app.get("/api/auth/me", response_model=LoginUser)
def me(request: Request) -> LoginUser:
    return auth_user(request)


@app.get("/api/entities", response_model=List[EntityOut])
def list_entities(request: Request) -> List[EntityOut]:
    auth_user(request)
    return [EntityOut(**e) for e in sorted(entities.values(), key=lambda x: x["createdAt"], reverse=True)]


@app.post("/api/entities", response_model=EntityOut)
def create_entity(request: Request, payload: EntityIn) -> EntityOut:
    auth_user(request)
    entity_id = uuid4().hex
    entity = EntityOut(id=entity_id, createdAt=now_iso(), **payload.model_dump())
    entities[entity_id] = entity.model_dump()
    return entity


@app.delete("/api/entities")
def delete_entities(request: Request) -> Dict[str, bool]:
    auth_user(request)
    entities.clear()
    return {"ok": True}


@app.delete("/api/entities/{entity_id}")
def delete_entity(request: Request, entity_id: str) -> Dict[str, bool]:
    auth_user(request)
    if entity_id not in entities:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del entities[entity_id]
    return {"ok": True}


@app.get("/api/entities/{entity_id}", response_model=EntityOut)
def get_entity(request: Request, entity_id: str) -> EntityOut:
    auth_user(request)
    entity = entities.get(entity_id)
    if not entity:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    return EntityOut(**entity)

