(function () {
  const AUTH_KEY = 'app:auth';
  const ENTITIES_KEY = 'app:entities';

  const $ = (sel) => document.querySelector(sel);

  const state = {
    auth: null,
    entities: [],
  };

  const api = {
    list() {
      try {
        return JSON.parse(localStorage.getItem(ENTITIES_KEY) || '[]');
      } catch {
        return [];
      }
    },
    create(obj) {
      const item = {
        ...obj,
        id: (crypto && crypto.randomUUID) ? crypto.randomUUID() : String(Date.now() + Math.random()),
        createdAt: new Date().toISOString(),
      };
      const list = api.list();
      list.push(item);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(list));
      return item;
    },
    remove(id) {
      const list = api.list().filter((x) => x.id !== id);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(list));
      return list;
    },
  };

  function seedEntities() {
    const existing = api.list();
    if (existing.length) return;
    const seeds = [
      { sku: 'SKU-1001', name: 'Kraft Shipping Boxes', qty: 42, threshold: 50, unitCost: 1.25, supplier: 'PackPro', status: 'low' },
      { sku: 'SKU-2004', name: 'Barcode Labels', qty: 180, threshold: 120, unitCost: 0.08, supplier: 'LabelWorks', status: 'ok' },
      { sku: 'SKU-3302', name: 'Reusable Tote Bags', qty: 16, threshold: 25, unitCost: 2.5, supplier: 'EcoSupply', status: 'low' },
      { sku: 'SKU-4407', name: 'Bubble Wrap Rolls', qty: 67, threshold: 40, unitCost: 4.75, supplier: 'PackPro', status: 'ok' },
      { sku: 'SKU-5510', name: 'Packing Tape', qty: 94, threshold: 75, unitCost: 1.9, supplier: 'OfficeHub', status: 'ok' },
    ].map((x) => ({
      ...x,
      value: Number((x.qty * x.unitCost).toFixed(2)),
      type: 'inventory',
    }));
    localStorage.setItem(ENTITIES_KEY, JSON.stringify(seeds));
  }

  function formatCurrency(n) {
    return new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' }).format(n || 0);
  }

  function getEntities() {
    return api.list().map((x) => ({
      ...x,
      qty: Number(x.qty || 0),
      threshold: Number(x.threshold || 0),
      unitCost: Number(x.unitCost || 0),
      value: Number(x.value || (Number(x.qty || 0) * Number(x.unitCost || 0))),
      status: x.status || (Number(x.qty || 0) <= Number(x.threshold || 0) ? 'low' : 'ok'),
    }));
  }

  function renderKpis() {
    const entities = state.entities;
    const totalStockValue = entities.reduce((sum, x) => sum + (x.value || x.qty * x.unitCost || 0), 0);
    const lowCount = entities.filter((x) => (x.qty || 0) <= (x.threshold || 0)).length;
    const pendingPOs = entities.filter((x) => x.type === 'po' && x.status === 'pending').length;
    const totalQty = entities.reduce((sum, x) => sum + (x.qty || 0), 0);

    const strip = $('#kpi-strip');
    if (!strip) return;
    strip.innerHTML = [
      { label: 'Total stock value', value: formatCurrency(totalStockValue) },
      { label: 'Below threshold', value: String(lowCount) },
      { label: 'Pending POs', value: String(pendingPOs) },
      { label: 'Units on hand', value: String(totalQty) },
    ]
      .map(
        (kpi) => `
          <div class="kpi-card" style="padding:12px;border:1px solid #ddd;border-radius:10px;min-width:140px;">
            <div style="font-size:12px;opacity:.7;">${kpi.label}</div>
            <div style="font-size:20px;font-weight:700;margin-top:4px;">${kpi.value}</div>
          </div>`
      )
      .join('');
  }

  function renderList() {
    const list = $('#entity-list');
    if (!list) return;
    const entities = state.entities;

    if (!entities.length) {
      list.innerHTML = '<p>No inventory items found.</p>';
      return;
    }

    const rows = entities
      .map((x) => {
        const low = (x.qty || 0) <= (x.threshold || 0);
        const badge = low ? '<span style="padding:2px 8px;border-radius:999px;background:#fee2e2;color:#991b1b;">Low</span>' : '<span style="padding:2px 8px;border-radius:999px;background:#dcfce7;color:#166534;">OK</span>';
        return `
          <tr data-id="${x.id}">
            <td>${escapeHtml(x.sku || '')}</td>
            <td>${escapeHtml(x.name || '')}</td>
            <td>${x.type === 'po' ? 'PO' : 'Inventory'}</td>
            <td>${x.qty}</td>
            <td>${x.threshold}</td>
            <td>${formatCurrency(x.unitCost)}</td>
            <td>${formatCurrency(x.value || x.qty * x.unitCost)}</td>
            <td>${badge}</td>
            <td><button class="delete-btn" data-delete="${x.id}">Delete</button></td>
          </tr>`;
      })
      .join('');

    list.innerHTML = `
      <table style="width:100%;border-collapse:collapse;">
        <thead>
          <tr>
            <th align="left">SKU</th>
            <th align="left">Name</th>
            <th align="left">Type</th>
            <th align="left">Qty</th>
            <th align="left">Threshold</th>
            <th align="left">Unit Cost</th>
            <th align="left">Value</th>
            <th align="left">Status</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>`;
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
  }

  function showApp() {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (loginView) loginView.style.display = 'none';
    if (appView) appView.style.display = '';
  }

  function showLogin() {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (loginView) loginView.style.display = '';
    if (appView) appView.style.display = 'none';
  }

  function hydrate() {
    state.entities = getEntities();
    renderKpis();
    renderList();
  }

  function initAuth() {
    const stored = localStorage.getItem(AUTH_KEY);
    if (stored) {
      try {
        state.auth = JSON.parse(stored);
        showApp();
        return true;
      } catch {
        localStorage.removeItem(AUTH_KEY);
      }
    }
    showLogin();
    return false;
  }

  function bindAuth() {
    const loginBtn = $('#login-btn');
    const logoutBtn = $('#logout-btn');
    const loginError = $('#login-error');

    if (loginBtn) {
      loginBtn.addEventListener('click', () => {
        const email = ($('#login-email') && $('#login-email').value || '').trim();
        const password = ($('#login-password') && $('#login-password').value || '').trim();

        if (email === 'demo@example.com' && password === 'demo') {
          const auth = { email, loggedAt: new Date().toISOString() };
          localStorage.setItem(AUTH_KEY, JSON.stringify(auth));
          state.auth = auth;
          if (loginError) loginError.textContent = '';
          showApp();
          hydrate();
        } else if (loginError) {
          loginError.textContent = 'Invalid credentials. Try demo@example.com / demo';
        }
      });
    }

    if (logoutBtn) {
      logoutBtn.addEventListener('click', () => {
        localStorage.removeItem(AUTH_KEY);
        location.reload();
      });
    }
  }

  function bindCreateForm() {
    const form = $('#create-form');
    if (!form) return;

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const get = (name) => form.querySelector(`[name="${name}"]`);
      const sku = (get('sku') && get('sku').value || '').trim();
      const name = (get('name') && get('name').value || '').trim();
      const type = (get('type') && get('type').value || 'inventory').trim();
      const qty = Number((get('qty') && get('qty').value) || 0);
      const threshold = Number((get('threshold') && get('threshold').value) || 0);
      const unitCost = Number((get('unitCost') && get('unitCost').value) || 0);
      const supplier = (get('supplier') && get('supplier').value || '').trim();

      if (!sku || !name) return;

      const created = api.create({
        sku,
        name,
        type,
        qty,
        threshold,
        unitCost,
        supplier,
        value: Number((qty * unitCost).toFixed(2)),
        status: qty <= threshold ? 'low' : 'ok',
      });

      form.reset();
      state.entities = getEntities();
      hydrate();
      return created;
    });
  }

  function bindDelete() {
    const list = $('#entity-list');
    if (!list) return;

    list.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-delete]');
      if (!btn) return;
      api.remove(btn.getAttribute('data-delete'));
      hydrate();
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedEntities();
    bindAuth();
    bindCreateForm();
    bindDelete();
    const authed = initAuth();
    if (authed) hydrate();
  });
})();

from datetime import datetime, timezone
from typing import Any, Dict, List, Optional
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, ConfigDict, EmailStr, Field

app = FastAPI(title="Inventory & Orders Tracker API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_USER = {
    "id": "demo-user",
    "email": "demo@example.com",
    "name": "Demo User",
}

DEMO_PASSWORD = "demo"

# In-memory storage for now; a real DB/repository layer would be swapped in here.
ENTITIES: Dict[str, Dict[str, Any]] = {}
TOKENS: Dict[str, Dict[str, Any]] = {}


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class LoginReq(BaseModel):
    email: EmailStr
    password: str


class UserOut(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    email: EmailStr
    name: str


class LoginResp(BaseModel):
    token: str
    user: UserOut


class EntityBase(BaseModel):
    title: str = Field(min_length=1, max_length=200)
    amount: float = Field(default=0)


class EntityCreate(EntityBase):
    pass


class EntityOut(EntityBase):
    model_config = ConfigDict(from_attributes=True)

    id: str
    createdAt: str


class HealthOut(BaseModel):
    status: str
    version: str


def parse_bearer_token(request: Request) -> str:
    auth = request.headers.get("authorization") or request.headers.get("Authorization")
    if not auth or not auth.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Not authenticated")
    token = auth.split(" ", 1)[1].strip()
    if not token:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Not authenticated")
    return token


def current_user_from_request(request: Request) -> Dict[str, Any]:
    token = parse_bearer_token(request)
    user = TOKENS.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    return user


@app.get("/api/health", response_model=HealthOut)
def health() -> HealthOut:
    return HealthOut(status="ok", version=app.version)


@app.post("/api/auth/login", response_model=LoginResp)
def login(payload: LoginReq) -> LoginResp:
    if payload.email.lower() != DEMO_USER["email"] or payload.password != DEMO_PASSWORD:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")

    token = uuid4().hex
    TOKENS[token] = DEMO_USER.copy()
    return LoginResp(token=token, user=UserOut(**DEMO_USER))


@app.get("/api/auth/me", response_model=UserOut)
def me(request: Request) -> UserOut:
    user = current_user_from_request(request)
    return UserOut(**user)


@app.get("/api/entities", response_model=List[EntityOut])
def list_entities(request: Request) -> List[EntityOut]:
    current_user_from_request(request)
    return [EntityOut(**entity) for entity in ENTITIES.values()]


@app.post("/api/entities", response_model=EntityOut)
def create_entity(payload: EntityCreate, request: Request) -> EntityOut:
    current_user_from_request(request)
    entity_id = uuid4().hex
    entity = {
        "id": entity_id,
        "createdAt": utc_now_iso(),
        "title": payload.title,
        "amount": payload.amount,
    }
    ENTITIES[entity_id] = entity
    return EntityOut(**entity)


@app.delete("/api/entities")
def delete_entities(request: Request) -> Dict[str, bool]:
    current_user_from_request(request)
    ENTITIES.clear()
    return {"ok": True}

