    host.querySelectorAll('[data-remove-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        api.remove(btn.getAttribute('data-remove-id'));
        renderKpis();
        renderList();
      });
    });
  }

  function escapeHtml(str) {
    return String(str)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function wireLogin() {
    const btn = $('#login-btn');
    const emailInput = $('#login-email');
    const passwordInput = $('#login-password');
    const error = $('#login-error');

    if (!btn || !emailInput || !passwordInput) return;

    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const email = emailInput.value.trim();
      const password = passwordInput.value;

      if (email === 'demo@example.com' && password === 'demo') {
        localStorage.setItem(
          AUTH_KEY,
          JSON.stringify({ email, loggedAt: new Date().toISOString() })
        );
        if (error) error.textContent = '';
        setView(true);
        renderKpis();
        renderList();
      } else if (error) {
        error.textContent = 'Invalid demo credentials. Try demo@example.com / demo';
      }
    });
  }

  function wireLogout() {
    const btn = $('#logout-btn');
    if (!btn) return;
    btn.addEventListener('click', () => {
      localStorage.removeItem(AUTH_KEY);
      location.reload();
    });
  }

  function wireCreateForm() {
    const form = $('#create-form');
    if (!form) return;

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(form);
      const payload = {
        contactName: String(formData.get('contactName') || '').trim(),
        email: String(formData.get('email') || '').trim(),
        dealName: String(formData.get('dealName') || '').trim(),
        stage: String(formData.get('stage') || 'Lead'),
        value: Number(formData.get('value') || 0),
        expectedClose: String(formData.get('expectedClose') || '').trim()
      };

      if (!payload.contactName || !payload.email || !payload.dealName) return;
      if (!STAGES.includes(payload.stage)) payload.stage = 'Lead';

      api.create(payload);
      form.reset();

      const stageField = form.querySelector('[name="stage"]');
      if (stageField) stageField.value = 'Lead';

      renderKpis();
      renderList();
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');

    seedEntities();

    const auth = getAuth();
    setView(Boolean(auth));

    wireLogin();
    wireLogout();
    wireCreateForm();

    if (auth) {
      renderKpis();
      renderList();
    }
  });
})();

from fastapi import FastAPI, HTTPException, Header, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field
from typing import Optional, Any
from uuid import uuid4
from datetime import datetime, timezone
import os

APP_VERSION = os.getenv("APP_VERSION", "1.0.0")

app = FastAPI(title="CRM Sales Pipeline API", version=APP_VERSION)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_EMAIL = "demo@example.com"
DEMO_PASSWORD = "demo"

tokens: dict[str, dict[str, Any]] = {}
entities: dict[str, dict[str, Any]] = {}
# Real database storage would be wired in here instead of the in-memory dicts above.


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class LoginReq(BaseModel):
    email: EmailStr
    password: str = Field(min_length=1)


class UserOut(BaseModel):
    id: str
    email: EmailStr
    name: str


class LoginResp(BaseModel):
    token: str
    user: UserOut


class EntityIn(BaseModel):
    title: str
    amount: float = 0
    contact: Optional[str] = None
    email: Optional[EmailStr] = None
    stage: Optional[str] = None
    expectedCloseDate: Optional[str] = None
    notes: Optional[str] = None
    activity: Optional[list[Any]] = None


class EntityOut(EntityIn):
    id: str
    createdAt: str


@app.post("/api/auth/login", response_model=LoginResp)
def login(req: LoginReq):
    if req.email.lower() != DEMO_EMAIL or req.password != DEMO_PASSWORD:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid email or password",
        )

    user = UserOut(id="demo-user", email=DEMO_EMAIL, name="Demo User")
    token = uuid4().hex
    tokens[token] = user.model_dump()
    return LoginResp(token=token, user=user)


def get_token_from_header(authorization: Optional[str]) -> str:
    if not authorization:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Missing Authorization header",
        )
    if not authorization.startswith("Bearer "):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid Authorization header",
        )
    token = authorization.removeprefix("Bearer ").strip()
    if not token:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid Authorization header",
        )
    return token


@app.get("/api/auth/me", response_model=UserOut)
def me(authorization: Optional[str] = Header(default=None)):
    token = get_token_from_header(authorization)
    user = tokens.get(token)
    if not user:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid or expired token",
        )
    return UserOut(**user)


@app.get("/api/entities", response_model=list[EntityOut])
def list_entities():
