(() => {
  const AUTH_KEY = 'app:auth';
  const ENTITIES_KEY = 'app:entities';
  const DEMO_EMAIL = 'demo@example.com';
  const DEMO_PASSWORD = 'demo';

  const $ = (sel) => document.querySelector(sel);
  const byId = (id) => document.getElementById(id);

  const state = {
    query: '',
    filterStatus: 'all',
    sortKey: 'createdAt',
    sortDir: 'desc'
  };

  const api = {
    list() {
      try {
        return JSON.parse(localStorage.getItem(ENTITIES_KEY) || '[]');
      } catch {
        return [];
      }
    },
    save(list) {
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(list));
      return list;
    },
    create(obj) {
      const list = api.list();
      const item = {
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        history: [
          {
            at: new Date().toISOString(),
            action: 'created',
            by: 'system',
            changes: { ...obj }
          }
        ],
        ...obj
      };
      list.push(item);
      api.save(list);
      return item;
    },
    remove(id) {
      const list = api.list().filter((item) => item.id !== id);
      api.save(list);
    }
  };

  function seedIfNeeded() {
    if (api.list().length) return;
    const seed = [
      {
        type: 'customer',
        name: 'Northwind Trading',
        email: 'ops@northwind.com',
        status: 'active',
        amount: 12450
      },
      {
        type: 'order',
        name: 'Q3 Inventory Restock',
        email: 'orders@acme.co',
        status: 'pending',
        amount: 8400
      },
      {
        type: 'staff',
        name: 'Ava Chen',
        email: 'ava.chen@internal.io',
        status: 'active',
        amount: 0
      },
      {
        type: 'customer',
        name: 'Blue Peak Logistics',
        email: 'contact@bluepeak.io',
        status: 'inactive',
        amount: 2650
      }
    ];
    localStorage.setItem(
      ENTITIES_KEY,
      JSON.stringify(
        seed.map((item) => ({
          id: crypto.randomUUID(),
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          history: [
            {
              at: new Date().toISOString(),
              action: 'seeded',
              by: 'system',
              changes: { ...item }
            }
          ],
          ...item
        }))
      )
    );
  }

  function getAuth() {
    try {
      return JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
    } catch {
      return null;
    }
  }

  function setAuth(payload) {
    localStorage.setItem(AUTH_KEY, JSON.stringify(payload));
  }

  function clearAuth() {
    localStorage.removeItem(AUTH_KEY);
  }

  function show(el, yes = true) {
    if (!el) return;
    el.style.display = yes ? '' : 'none';
  }

  function formatCurrency(n) {
    const value = Number(n || 0);
    return value.toLocaleString(undefined, { style: 'currency', currency: 'USD' });
  }

  function escapeHtml(str) {
    return String(str ?? '').replace(/[&<>"']/g, (m) => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;'
    }[m]));
  }

  function getFilteredList() {
    let list = api.list();

    if (state.query) {
      const q = state.query.toLowerCase();
      list = list.filter((item) =>
        [item.name, item.email, item.type, item.status].some((v) => String(v || '').toLowerCase().includes(q))
      );
    }

    if (state.filterStatus !== 'all') {
      list = list.filter((item) => String(item.status || '').toLowerCase() === state.filterStatus);
    }

    list.sort((a, b) => {
      const av = a[state.sortKey] ?? '';
      const bv = b[state.sortKey] ?? '';
      const cmp = String(av).localeCompare(String(bv), undefined, { numeric: true });
      return state.sortDir === 'asc' ? cmp : -cmp;
    });

    return list;
  }

  function renderKpis() {
    const list = api.list();
    const total = list.length;
    const active = list.filter((x) => String(x.status).toLowerCase() === 'active').length;
    const pending = list.filter((x) => String(x.status).toLowerCase() === 'pending').length;
    const amount = list.reduce((sum, x) => sum + Number(x.amount || 0), 0);

    const strip = byId('kpi-strip');
    if (!strip) return;
    strip.innerHTML = `
      <div class="kpi"><strong>${total}</strong><span>Total Records</span></div>
      <div class="kpi"><strong>${active}</strong><span>Active</span></div>
      <div class="kpi"><strong>${pending}</strong><span>Pending</span></div>
      <div class="kpi"><strong>${formatCurrency(amount)}</strong><span>Value</span></div>
    `;
  }

  function renderList() {
    const target = byId('entity-list');
    if (!target) return;

    const list = getFilteredList();
    if (!list.length) {
      target.innerHTML = '<p class="empty">No records match your search.</p>';
      return;
    }

    target.innerHTML = `
      <table class="data-table">
        <thead>
          <tr>
            <th>Type</th>
            <th>Name</th>
            <th>Email</th>
            <th>Status</th>
            <th>Amount</th>
            <th>Created</th>
            <th>Audit</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          ${list.map((item) => `
            <tr>
              <td>${escapeHtml(item.type)}</td>
              <td>${escapeHtml(item.name)}</td>
              <td>${escapeHtml(item.email || '')}</td>
              <td>${escapeHtml(item.status || '')}</td>
              <td>${formatCurrency(item.amount)}</td>
              <td>${new Date(item.createdAt).toLocaleString()}</td>
              <td>${(item.history || []).length} events</td>
              <td><button data-delete-id="${escapeHtml(item.id)}" class="danger-btn">Delete</button></td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    `;

    target.querySelectorAll('[data-delete-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-delete-id');
        api.remove(id);
        renderAll();
      });
    });
  }

  function renderAll() {
    renderKpis();
    renderList();
  }

  function wireApp() {
    const createForm = byId('create-form');
    const logoutBtn = byId('logout-btn');
    const searchInput = byId('search-input');
    const statusFilter = byId('status-filter');
    const sortSelect = byId('sort-select');
    const sortDirBtn = byId('sort-dir-btn');

    if (createForm) {
      createForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const fd = new FormData(createForm);
        const data = Object.fromEntries(fd.entries());

        api.create({
          type: data.type || 'customer',
          name: data.name || 'Untitled',
          email: data.email || '',
          status: data.status || 'active',
          amount: Number(data.amount || 0)
        });

        createForm.reset();
        renderAll();
      });
    }

    if (logoutBtn) {
      logoutBtn.addEventListener('click', () => {
        clearAuth();
        location.reload();
      });
    }

    if (searchInput) {
      searchInput.addEventListener('input', () => {
        state.query = searchInput.value.trim();
        renderList();
      });
    }

    if (statusFilter) {
      statusFilter.addEventListener('change', () => {
        state.filterStatus = statusFilter.value;
        renderList();
      });
    }

    if (sortSelect) {
      sortSelect.addEventListener('change', () => {
        state.sortKey = sortSelect.value;
        renderList();
      });
    }

    if (sortDirBtn) {
      sortDirBtn.addEventListener('click', () => {
        state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';
        sortDirBtn.textContent = state.sortDir === 'asc' ? 'Ascending' : 'Descending';
        renderList();
      });
    }
  }

  function wireAuth() {
    const loginBtn = byId('login-btn');
    const loginError = byId('login-error');

    if (!loginBtn) return;

    loginBtn.addEventListener('click', () => {
      const email = (byId('login-email')?.value || '').trim();
      const password = byId('login-password')?.value || '';

      if (email === DEMO_EMAIL && password === DEMO_PASSWORD) {
        if (loginError) loginError.textContent = '';
        setAuth({ email, loggedAt: new Date().toISOString() });
        show(byId('login-view'), false);
        show(byId('app-view'), true);
        renderAll();
      } else if (loginError) {
        loginError.textContent = 'Invalid demo credentials.';
      }
    });
  }

  function initVisibility() {
    const auth = getAuth();
    const loginView = byId('login-view');
    const appView = byId('app-view');

    if (auth?.email) {
      show(loginView, false);
      show(appView, true);
    } else {
      show(loginView, true);
      show(appView, false);
    }
  }

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedIfNeeded();
    initVisibility();
    wireAuth();
    wireApp();
    renderAll();
  });
})();

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Literal
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Header, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field

app = FastAPI(title="Internal Admin Portal API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_EMAIL = "demo@example.com"
DEMO_PASSWORD = "demo"

# In-memory demo storage. Replace with a real database/ORM/repository layer in production.
entities: dict[str, dict[str, Any]] = {}
sessions: dict[str, dict[str, Any]] = {}


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class LoginReq(BaseModel):
    email: EmailStr
    password: str = Field(min_length=1)


class User(BaseModel):
    id: str
    email: EmailStr
    name: str
    role: Literal["admin", "editor", "viewer"]


class LoginResp(BaseModel):
    token: str
    user: User


class EntityBase(BaseModel):
    title: str
    amount: float


class EntityCreate(EntityBase):
    pass


class Entity(EntityBase):
    id: str
    createdAt: str


class ApiStatus(BaseModel):
    status: str
    version: str


def demo_user() -> dict[str, Any]:
    return {
        "id": "demo-user",
        "email": DEMO_EMAIL,
        "name": "Demo Admin",
        "role": "admin",
    }


def get_bearer_token(authorization: str | None) -> str:
    if not authorization:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Missing Authorization header")
    prefix = "Bearer "
    if not authorization.startswith(prefix):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid Authorization header")
    token = authorization[len(prefix):].strip()
    if not token:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Missing token")
    return token


def require_user(authorization: str | None) -> dict[str, Any]:
    token = get_bearer_token(authorization)
    user = sessions.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid or expired token")
    return user


@app.get("/api/health", response_model=ApiStatus)
def health() -> dict[str, str]:
    return {"status": "ok", "version": app.version}


@app.post("/api/auth/login", response_model=LoginResp)
def login(req: LoginReq) -> dict[str, Any]:
    if req.email.lower() != DEMO_EMAIL or req.password != DEMO_PASSWORD:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")
    token = uuid4().hex
    user = demo_user()
    sessions[token] = user
    return {"token": token, "user": user}


@app.get("/api/auth/me", response_model=User)
def me(authorization: str | None = Header(default=None)) -> dict[str, Any]:
    return require_user(authorization)


@app.get("/api/entities", response_model=list[Entity])
def list_entities(authorization: str | None = Header(default=None)) -> list[dict[str, Any]]:
    require_user(authorization)
    return list(entities.values())


@app.post("/api/entities", response_model=Entity, status_code=status.HTTP_201_CREATED)
def create_entity(payload: EntityCreate, authorization: str | None = Header(default=None)) -> dict[str, Any]:
    require_user(authorization)
    entity = {
        "id": uuid4().hex,
        "createdAt": now_iso(),
        **payload.model_dump(),
    }
    entities[entity["id"]] = entity
    return entity


@app.delete("/api/entities")
def delete_entity(id: str, authorization: str | None = Header(default=None)) -> dict[str, bool]:
    require_user(authorization)
    if id not in entities:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del entities[id]
    return {"success": True}

