(function () {
  const AUTH_KEY = 'app:auth';
  const ENTITIES_KEY = 'app:entities';

  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => Array.from(document.querySelectorAll(sel));

  const state = {
    auth: null,
    entities: [],
  };

  const api = {
    list() {
      try {
        return JSON.parse(localStorage.getItem(ENTITIES_KEY) || '[]');
      } catch {
        return [];
      }
    },
    create(obj) {
      const current = api.list();
      const created = {
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        ...obj,
      };
      current.push(created);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(current));
      return created;
    },
    remove(id) {
      const next = api.list().filter((item) => item.id !== id);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(next));
      return next;
    },
    update(id, patch) {
      const next = api.list().map((item) => (item.id === id ? { ...item, ...patch } : item));
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(next));
      return next.find((item) => item.id === id) || null;
    },
  };

  function seedEntities() {
    const existing = api.list();
    if (existing.length) return;
    const samples = [
      {
        type: 'Restaurant',
        name: 'Sunset Grill',
        amount: 49,
        status: 'Active',
        location: 'Downtown',
      },
      {
        type: 'Order',
        name: 'Order #1001',
        amount: 36.5,
        status: 'Received',
        location: 'Main Street',
      },
      {
        type: 'Order',
        name: 'Order #1002',
        amount: 58.25,
        status: 'Preparing',
        location: 'Main Street',
      },
      {
        type: 'Restaurant',
        name: 'Pasta Point',
        amount: 49,
        status: 'Trial',
        location: 'West Side',
      },
      {
        type: 'Order',
        name: 'Order #1003',
        amount: 22,
        status: 'Ready',
        location: 'Uptown',
      },
    ];
    localStorage.setItem(
      ENTITIES_KEY,
      JSON.stringify(samples.map((x) => ({ ...x, id: crypto.randomUUID(), createdAt: new Date().toISOString() })))
    );
  }

  function getAuth() {
    try {
      return JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
    } catch {
      return null;
    }
  }

  function setView(authed) {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (loginView) loginView.style.display = authed ? 'none' : '';
    if (appView) appView.style.display = authed ? '' : 'none';
  }

  function renderList() {
    const container = $('#entity-list');
    if (!container) return;

    const entities = api.list();
    state.entities = entities;

    if (!entities.length) {
      container.innerHTML = '<p>No records yet.</p>';
      return;
    }

    const rows = entities
      .slice()
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
      .map((item) => {
        const amount = typeof item.amount === 'number' ? `$${item.amount.toFixed(2)}` : '—';
        const created = item.createdAt ? new Date(item.createdAt).toLocaleString() : '—';
        return `
          <tr>
            <td>${escapeHtml(item.name || '')}</td>
            <td>${escapeHtml(item.type || '')}</td>
            <td>${escapeHtml(item.status || '')}</td>
            <td>${escapeHtml(item.location || '')}</td>
            <td>${amount}</td>
            <td>${created}</td>
            <td><button data-remove-id="${item.id}" type="button">Remove</button></td>
          </tr>
        `;
      })
      .join('');

    container.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Type</th>
            <th>Status</th>
            <th>Location</th>
            <th>Amount</th>
            <th>Created</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;

    $$('[data-remove-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        api.remove(btn.getAttribute('data-remove-id'));
        renderList();
        renderKpis();
      });
    });
  }

  function renderKpis() {
    const strip = $('#kpi-strip');
    if (!strip) return;

    const entities = api.list();
    const total = entities.length;
    const revenue = entities.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
    const active = entities.filter((item) => String(item.status || '').toLowerCase() === 'active').length;
    const preparing = entities.filter((item) => String(item.status || '').toLowerCase() === 'preparing').length;

    strip.innerHTML = `
      <div class="kpi"><strong>${total}</strong><span>Total records</span></div>
      <div class="kpi"><strong>$${revenue.toFixed(2)}</strong><span>Amount sum</span></div>
      <div class="kpi"><strong>${active}</strong><span>Active</span></div>
      <div class="kpi"><strong>${preparing}</strong><span>Preparing</span></div>
    `;
  }

  function escapeHtml(value) {
    return String(value)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function initAuth() {
    const auth = getAuth();
    if (auth && auth.email) {
      state.auth = auth;
      setView(true);
      return true;
    }
    setView(false);
    return false;
  }

  function bindLogin() {
    const loginBtn = $('#login-btn');
    const loginError = $('#login-error');
    const emailInput = $('#login-email');
    const passwordInput = $('#login-password');

    if (!loginBtn) return;

    loginBtn.addEventListener('click', (e) => {
      e.preventDefault();
      const email = (emailInput && emailInput.value || '').trim();
      const password = (passwordInput && passwordInput.value || '').trim();

      if (email === 'demo@example.com' && password === 'demo') {
        const auth = { email, loggedAt: new Date().toISOString() };
        localStorage.setItem(AUTH_KEY, JSON.stringify(auth));
        state.auth = auth;
        if (loginError) loginError.textContent = '';
        setView(true);
        renderList();
        renderKpis();
        return;
      }

      if (loginError) loginError.textContent = 'Invalid demo credentials. Try demo@example.com / demo.';
    });
  }

  function bindLogout() {
    const logoutBtn = $('#logout-btn');
    if (!logoutBtn) return;
    logoutBtn.addEventListener('click', () => {
      localStorage.removeItem(AUTH_KEY);
      location.reload();
    });
  }

  function bindCreateForm() {
    const form = $('#create-form');
    if (!form) return;

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const fd = new FormData(form);
      const payload = {
        name: String(fd.get('name') || fd.get('entity-name') || '').trim(),
        type: String(fd.get('type') || fd.get('entity-type') || 'Order').trim(),
        status: String(fd.get('status') || fd.get('entity-status') || 'Received').trim(),
        location: String(fd.get('location') || fd.get('entity-location') || '').trim(),
        amount: Number(fd.get('amount') || fd.get('entity-amount') || 0),
      };

      if (!payload.name) return;

      api.create(payload);
      form.reset();
      renderList();
      renderKpis();
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');

    seedEntities();
    initAuth();
    bindLogin();
    bindLogout();
    bindCreateForm();

    if (state.auth) {
      renderList();
      renderKpis();
    }
  });
})();

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field

app = FastAPI(title="Restaurant Ordering API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_EMAIL = "demo@example.com"
DEMO_PASSWORD = "demo"
DEMO_USER = {
    "id": "demo-user",
    "email": DEMO_EMAIL,
    "name": "Demo User",
    "role": "admin",
}

# In-memory storage for now; a real database/tenant-aware persistence layer would slot in here.
entities: dict[str, dict[str, Any]] = {}
tokens: dict[str, dict[str, Any]] = {}


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def auth_user_from_request(request: Request) -> dict[str, Any]:
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Missing bearer token")
    token = auth.removeprefix("Bearer ").strip()
    user = tokens.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    return user


class LoginReq(BaseModel):
    email: EmailStr
    password: str


class LoginResp(BaseModel):
    token: str
    user: dict[str, Any]


class EntityCreateReq(BaseModel):
    title: str = Field(min_length=1)
    amount: float = Field(ge=0)
    description: str | None = None
    category: str | None = None


class EntityResp(BaseModel):
    id: str
    createdAt: str
    title: str
    amount: float
    description: str | None = None
    category: str | None = None


@app.get("/api/health")
async def health() -> dict[str, str]:
    return {"status": "ok", "version": app.version}


@app.post("/api/auth/login")
async def login(req: LoginReq) -> dict[str, Any]:
    if req.email != DEMO_EMAIL or req.password != DEMO_PASSWORD:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")
    token = uuid4().hex
    tokens[token] = DEMO_USER
    return {"token": token, "user": DEMO_USER}


@app.get("/api/auth/me")
async def me(request: Request) -> dict[str, Any]:
    return auth_user_from_request(request)


@app.get("/api/entities")
async def list_entities(request: Request) -> list[dict[str, Any]]:
    auth_user_from_request(request)
    return list(entities.values())


@app.post("/api/entities")
async def create_entity(request: Request, req: EntityCreateReq) -> dict[str, Any]:
    auth_user_from_request(request)
    entity = {
        "id": uuid4().hex,
        "createdAt": now_iso(),
        "title": req.title,
        "amount": req.amount,
        "description": req.description,
        "category": req.category,
    }
    entities[entity["id"]] = entity
    return entity


@app.delete("/api/entities")
async def delete_entity(request: Request, entity_id: str) -> dict[str, bool]:
    auth_user_from_request(request)
    if entity_id not in entities:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del entities[entity_id]
    return {"ok": True}

