from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Dict, List, Optional
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, ConfigDict, EmailStr, Field


APP_VERSION = "1.0.0"

app = FastAPI(title="Healthcare Practice Portal API", version=APP_VERSION)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_USER = {
    "id": "demo-user",
    "email": "demo@example.com",
    "name": "Demo User",
    "role": "admin",
}

TOKENS: Dict[str, Dict[str, Any]] = {}
ENTITIES: Dict[str, Dict[str, Any]] = {}
# Real persistence would replace the in-memory dicts above with a database/repository layer.


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class LoginReq(BaseModel):
    email: EmailStr
    password: str


class UserOut(BaseModel):
    id: str
    email: EmailStr
    name: str
    role: str


class AuthOut(BaseModel):
    token: str
    user: UserOut


class EntityBase(BaseModel):
    title: str = Field(min_length=1, max_length=255)
    amount: float = Field(default=0)
    description: Optional[str] = None
    status: Optional[str] = None
    metadata: Dict[str, Any] = Field(default_factory=dict)


class EntityCreate(EntityBase):
    pass


class EntityOut(EntityBase):
    id: str
    createdAt: str


def to_user_out(user: Dict[str, Any]) -> UserOut:
    return UserOut(**user)


def get_bearer_token(request: Request) -> str:
    auth = request.headers.get("authorization", "")
    if not auth.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Missing bearer token")
    token = auth.removeprefix("Bearer ").strip()
    if not token:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Missing bearer token")
    return token


def get_current_user(request: Request) -> Dict[str, Any]:
    token = get_bearer_token(request)
    user = TOKENS.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid or expired token")
    return user


@app.get("/api/health")
def health() -> Dict[str, str]:
    return {"status": "ok", "version": APP_VERSION}


@app.post("/api/auth/login", response_model=AuthOut)
def login(payload: LoginReq) -> AuthOut:
    if payload.email.lower() != DEMO_USER["email"] or payload.password != "demo":
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")

    token = uuid4().hex
    TOKENS[token] = DEMO_USER.copy()
    return AuthOut(token=token, user=to_user_out(DEMO_USER))


@app.get("/api/auth/me", response_model=UserOut)
def me(request: Request) -> UserOut:
    return to_user_out(get_current_user(request))


@app.get("/api/entities", response_model=List[EntityOut])
def list_entities(request: Request) -> List[EntityOut]:
    _ = get_current_user(request)
    return [EntityOut(**entity) for entity in ENTITIES.values()]


@app.post("/api/entities", response_model=EntityOut, status_code=status.HTTP_201_CREATED)
def create_entity(request: Request, payload: EntityCreate) -> EntityOut:
    _ = get_current_user(request)
    entity_id = uuid4().hex
    entity = {
        "id": entity_id,
        "createdAt": now_iso(),
        **payload.model_dump(),
    }
    ENTITIES[entity_id] = entity
    return EntityOut(**entity)


@app.delete("/api/entities")
def delete_entity(request: Request, id: str) -> Dict[str, bool]:
    _ = get_current_user(request)
    if id not in ENTITIES:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del ENTITIES[id]
    return {"ok": True}

