(() => {
  const AUTH_KEY = 'app:auth';
  const ENTITIES_KEY = 'app:entities';
  const DEMO_EMAIL = 'demo@example.com';
  const DEMO_PASSWORD = 'demo';

  const $ = (sel) => document.querySelector(sel);
  const show = (el) => el && (el.style.display = '');
  const hide = (el) => el && (el.style.display = 'none');

  const api = {
    list() {
      try {
        return JSON.parse(localStorage.getItem(ENTITIES_KEY) || '[]');
      } catch {
        return [];
      }
    },
    create(obj) {
      const current = api.list();
      const item = {
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        ...obj
      };
      current.push(item);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(current));
      return item;
    },
    remove(id) {
      const next = api.list().filter((x) => x.id !== id);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(next));
      return next;
    }
  };

  function seedIfEmpty() {
    if (api.list().length) return;
    const seeds = [
      {
        type: 'announcement',
        title: 'Welcome to Event Community App',
        status: 'published',
        amount: 0,
        description: 'Your all-in-one event workspace for attendees, speakers, and organisers.'
      },
      {
        type: 'session',
        title: 'Opening Keynote: Building Community Events',
        status: 'scheduled',
        amount: 125,
        description: 'A multi-track kickoff session about attendee engagement and networking.'
      },
      {
        type: 'speaker',
        title: 'Jordan Lee — Speaker Profile',
        status: 'active',
        amount: 1,
        description: 'Monitors live Q&A and owns session details.'
      },
      {
        type: 'attendee',
        title: 'Attendee Directory Snapshot',
        status: 'published',
        amount: 340,
        description: 'Discover peers, expand your network, and star sessions to your schedule.'
      }
    ];
    localStorage.setItem(
      ENTITIES_KEY,
      JSON.stringify(seeds.map((x) => ({ ...x, id: crypto.randomUUID(), createdAt: new Date().toISOString() })))
    );
  }

  function authState() {
    try {
      return JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
    } catch {
      return null;
    }
  }

  function setAppView(isAuthed) {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (!loginView || !appView) return;
    if (isAuthed) {
      hide(loginView);
      show(appView);
    } else {
      show(loginView);
      hide(appView);
    }
  }

  function renderKpis() {
    const strip = $('#kpi-strip');
    if (!strip) return;
    const items = api.list();
    const total = items.length;
    const published = items.filter((x) => x.status === 'published').length;
    const amountSum = items.reduce((sum, x) => sum + Number(x.amount || 0), 0);
    strip.innerHTML = `
      <div class="kpi"><strong>${total}</strong><span>Total items</span></div>
      <div class="kpi"><strong>${published}</strong><span>Published</span></div>
      <div class="kpi"><strong>${amountSum}</strong><span>Amount sum</span></div>
    `;
  }

  function renderList() {
    const mount = $('#entity-list');
    if (!mount) return;
    const items = api.list();
    if (!items.length) {
      mount.innerHTML = '<p>No entities yet.</p>';
      return;
    }

    const rows = items
      .map(
        (x) => `
        <tr>
          <td>${escapeHtml(x.type || '')}</td>
          <td>${escapeHtml(x.title || '')}</td>
          <td>${escapeHtml(x.status || '')}</td>
          <td>${escapeHtml(String(x.amount ?? ''))}</td>
          <td>${new Date(x.createdAt).toLocaleString()}</td>
          <td><button type="button" data-remove="${x.id}">Remove</button></td>
        </tr>`
      )
      .join('');

    mount.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Type</th><th>Title</th><th>Status</th><th>Amount</th><th>Created</th><th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;

    mount.querySelectorAll('[data-remove]').forEach((btn) => {
      btn.addEventListener('click', () => {
        api.remove(btn.getAttribute('data-remove'));
        renderKpis();
        renderList();
      });
    });
  }

  function escapeHtml(value) {
    return String(value)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function handleLogin() {
    const email = ($('#login-email')?.value || '').trim();
    const password = $('#login-password')?.value || '';
    const error = $('#login-error');

    if (email === DEMO_EMAIL && password === DEMO_PASSWORD) {
      localStorage.setItem(AUTH_KEY, JSON.stringify({ email, loggedAt: new Date().toISOString() }));
      if (error) error.textContent = '';
      setAppView(true);
      renderKpis();
      renderList();
      return;
    }

    if (error) error.textContent = 'Invalid demo credentials. Use demo@example.com / demo';
  }

  function bindEvents() {
    $('#login-btn')?.addEventListener('click', handleLogin);

    $('#logout-btn')?.addEventListener('click', () => {
      localStorage.removeItem(AUTH_KEY);
      location.reload();
    });

    $('#create-form')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const form = e.currentTarget;
      const formData = new FormData(form);
      const entity = {
        type: String(formData.get('type') || '').trim(),
        title: String(formData.get('title') || '').trim(),
        status: String(formData.get('status') || '').trim(),
        amount: Number(formData.get('amount') || 0),
        description: String(formData.get('description') || '').trim()
      };

      if (!entity.title) return;
      api.create(entity);
      form.reset();
      renderKpis();
      renderList();
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedIfEmpty();
    bindEvents();
    setAppView(!!authState());
    if (authState()) {
      renderKpis();
      renderList();
    }
  });
})();

