        type: 'Document',
        name: 'K-1 Package',
        lpName: 'Summit Capital',
        amount: 0,
        status: 'Uploaded',
      },
    ];
    localStorage.setItem(ENTITIES_KEY, JSON.stringify(seeded.map((x) => ({
      ...x,
      id: crypto.randomUUID(),
      createdAt: new Date().toISOString(),
    }))));
  };

  const money = (value) => {
    const n = Number(value || 0);
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(n);
  };

  const auth = {
    get() {
      try {
        return JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
      } catch {
        return null;
      }
    },
    set(payload) {
      localStorage.setItem(AUTH_KEY, JSON.stringify(payload));
    },
    clear() {
      localStorage.removeItem(AUTH_KEY);
    },
  };

  const showView = (view) => {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (loginView) loginView.style.display = view === 'login' ? '' : 'none';
    if (appView) appView.style.display = view === 'app' ? '' : 'none';
  };

  const renderKpis = () => {
    const strip = $('#kpi-strip');
    if (!strip) return;
    const list = api.list();
    const count = list.length;
    const totalAmount = list.reduce((sum, item) => sum + Number(item.amount || 0), 0);
    const pendingCalls = list.filter((i) => i.type === 'Capital Call' && i.status === 'Pending').length;
    const paidDistributions = list.filter((i) => i.type === 'Distribution' && i.status === 'Paid').length;

    strip.innerHTML = `
      <div class="kpi"><strong>${count}</strong><span>Records</span></div>
      <div class="kpi"><strong>${money(totalAmount)}</strong><span>Total Amount</span></div>
      <div class="kpi"><strong>${pendingCalls}</strong><span>Pending Calls</span></div>
      <div class="kpi"><strong>${paidDistributions}</strong><span>Paid Distributions</span></div>
    `;
  };

  const renderList = () => {
    const el = $('#entity-list');
    if (!el) return;
    const list = api.list().sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

    if (!list.length) {
      el.innerHTML = '<p>No records yet. Create the first investor update, capital call, distribution, or document.</p>';
      return;
    }

    const rows = list.map((item) => `
      <tr>
        <td>${item.type || ''}</td>
        <td>${item.name || ''}</td>
        <td>${item.lpName || ''}</td>
        <td>${money(item.amount)}</td>
        <td>${item.status || ''}</td>
        <td><button type="button" data-remove="${item.id}">Remove</button></td>
      </tr>
    `).join('');

    el.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Type</th>
            <th>Title</th>
            <th>LP</th>
            <th>Amount</th>
            <th>Status</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;

    el.querySelectorAll('[data-remove]').forEach((btn) => {
      btn.addEventListener('click', () => {
        api.remove(btn.getAttribute('data-remove'));
        renderList();
        renderKpis();
      });
    });
  };

  const initLogin = () => {
    const btn = $('#login-btn');
    const emailInput = $('#login-email');
    const passwordInput = $('#login-password');
    const errorEl = $('#login-error');

    if (!btn || !emailInput || !passwordInput) return;

    const attemptLogin = () => {
      const email = String(emailInput.value || '').trim();
      const password = String(passwordInput.value || '');
      if (email === DEMO_EMAIL && password === DEMO_PASSWORD) {
        auth.set({ email, loggedAt: new Date().toISOString() });
        showView('app');
        renderList();
        renderKpis();
        return;
      }
      if (errorEl) errorEl.textContent = 'Invalid demo credentials. Use demo@example.com / demo.';
    };

    btn.addEventListener('click', attemptLogin);
    [emailInput, passwordInput].forEach((input) => {
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') attemptLogin();
      });
    });
  };

  const initLogout = () => {
    const btn = $('#logout-btn');
    if (!btn) return;
    btn.addEventListener('click', () => {
      auth.clear();
      location.reload();
    });
  };

  const initCreateForm = () => {
    const form = $('#create-form');
    if (!form) return;
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const fd = new FormData(form);
      const payload = {
        type: String(fd.get('type') || 'Quarterly Update'),
        name: String(fd.get('name') || '').trim(),
        lpName: String(fd.get('lpName') || 'All LPs').trim(),
        amount: Number(fd.get('amount') || 0),
        status: String(fd.get('status') || 'Draft'),
      };
      if (!payload.name) return;
      api.create(payload);
      form.reset();
      renderList();
      renderKpis();
    });
  };

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedEntities();
    initLogin();
    initLogout();
    initCreateForm();

    if (auth.get()) {
      showView('app');
      renderList();
      renderKpis();
    } else {
      showView('login');
    }
  });
})();

from fastapi import FastAPI, HTTPException, Header, Depends
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field
from typing import Any, Optional, List, Dict
from uuid import uuid4
from datetime import datetime, timezone

app = FastAPI(title="Investor Reporting Dashboard API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_USER = {
    "id": "user_demo",
    "email": "demo@example.com",
    "name": "Demo User",
    "role": "admin",
}
DEMO_PASSWORD = "demo"

tokens: Dict[str, dict] = {}
entities: Dict[str, dict] = {}
# In production, this in-memory store would be replaced with a real database layer.


class LoginReq(BaseModel):
    email: str
    password: str


class LoginRes(BaseModel):
    token: str
    user: dict


class EntityIn(BaseModel):
    title: str
    amount: float = Field(default=0)
    description: Optional[str] = None
    lpId: Optional[str] = None
    fundId: Optional[str] = None
    status: Optional[str] = None
    metadata: Dict[str, Any] = Field(default_factory=dict)


class EntityOut(EntityIn):
    id: str
    createdAt: str


class HealthRes(BaseModel):
    status: str
    version: str


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def get_current_user(authorization: Optional[str] = Header(default=None)) -> dict:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Unauthorized")
    token = authorization.removeprefix("Bearer ").strip()
    user = tokens.get(token)
    if not user:
        raise HTTPException(status_code=401, detail="Unauthorized")
    return user


@app.post("/api/auth/login")
def login(payload: LoginReq):
    if payload.email != DEMO_USER["email"] or payload.password != DEMO_PASSWORD:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = uuid4().hex
    tokens[token] = DEMO_USER
    return {"token": token, "user": DEMO_USER}


@app.get("/api/auth/me")
def me(user: dict = Depends(get_current_user)):
    return user


@app.get("/api/entities")
def list_entities(user: dict = Depends(get_current_user)):
    return list(entities.values())


@app.post("/api/entities")
def create_entity(payload: EntityIn, user: dict = Depends(get_current_user)):
    entity_id = uuid4().hex
    entity = EntityOut(
        id=entity_id,
        createdAt=now_iso(),
        **payload.model_dump(),
    ).model_dump()
    entities[entity_id] = entity
    return entity


@app.delete("/api/entities")
def delete_entity(id: str, user: dict = Depends(get_current_user)):
    if id not in entities:
        raise HTTPException(status_code=404, detail="Entity not found")
    deleted = entities.pop(id)
    return deleted


@app.get("/api/health")
def health():
    return HealthRes(status="ok", version=app.version).model_dump()

