      },
    ].map((x) => ({
      ...x,
      createdAt: new Date().toISOString(),
      id: crypto.randomUUID(),
    }));
    writeJSON(ENTITY_KEY, seed);
  };

  const renderKpis = () => {
    const items = api.list();
    const total = items.length;
    const active = items.filter((x) => String(x.status).toLowerCase() === 'active').length;
    const pending = items.filter((x) => String(x.status).toLowerCase() === 'pending').length;
    const amountSum = items.reduce((sum, x) => sum + (Number(x.amount) || 0), 0);

    const strip = $('#kpi-strip');
    if (!strip) return;
    strip.innerHTML = '';
    const cards = [
      ['Total records', total],
      ['Active', active],
      ['Pending', pending],
      ['Amount sum', amountSum],
    ];
    cards.forEach(([label, value]) => {
      strip.appendChild(
        el('div', { className: 'kpi-card' }, [
          el('div', { className: 'kpi-label', text: label }),
          el('div', { className: 'kpi-value', text: String(value) }),
        ])
      );
    });
  };

  const renderList = () => {
    const container = $('#entity-list');
    if (!container) return;
    const items = api.list().sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
    container.innerHTML = '';

    if (!items.length) {
      container.appendChild(el('p', { text: 'No records yet.' }));
      return;
    }

    const table = el('table', { className: 'entity-table' });
    const thead = el('thead', {}, [
      el('tr', {}, [
        el('th', { text: 'Type' }),
        el('th', { text: 'Name' }),
        el('th', { text: 'Department' }),
        el('th', { text: 'Status' }),
        el('th', { text: 'Amount' }),
        el('th', { text: 'Created' }),
        el('th', { text: 'Actions' }),
      ]),
    ]);
    const tbody = el('tbody');

    items.forEach((item) => {
      const row = el('tr', {}, [
        el('td', { text: item.type || '—' }),
        el('td', { text: item.name || '—' }),
        el('td', { text: item.department || '—' }),
        el('td', { text: item.status || '—' }),
        el('td', { text: String(item.amount ?? 0) }),
        el('td', { text: item.createdAt ? new Date(item.createdAt).toLocaleString() : '—' }),
      ]);
      const removeBtn = el('button', {
        type: 'button',
        text: 'Delete',
        onclick: () => {
          api.remove(item.id);
          renderKpis();
          renderList();
        },
      });
      const actionCell = el('td');
      actionCell.appendChild(removeBtn);
      row.appendChild(actionCell);
      tbody.appendChild(row);
    });

    table.appendChild(thead);
    table.appendChild(tbody);
    container.appendChild(table);
  };

  const showApp = () => {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (loginView) loginView.style.display = 'none';
    if (appView) appView.style.display = '';
    renderKpis();
    renderList();
  };

  const showLogin = () => {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (loginView) loginView.style.display = '';
    if (appView) appView.style.display = 'none';
  };

  const bindAuth = () => {
    const loginBtn = $('#login-btn');
    const logoutBtn = $('#logout-btn');
    const errorEl = $('#login-error');

    if (loginBtn) {
      loginBtn.addEventListener('click', () => {
        const email = ($('#login-email')?.value || '').trim();
        const password = ($('#login-password')?.value || '').trim();
        if (email === DEMO_EMAIL && password === DEMO_PASSWORD) {
          writeJSON(AUTH_KEY, { email, loggedAt: new Date().toISOString() });
          if (errorEl) errorEl.textContent = '';
          showApp();
        } else if (errorEl) {
          errorEl.textContent = 'Invalid credentials. Use demo@example.com / demo.';
        }
      });
    }

    if (logoutBtn) {
      logoutBtn.addEventListener('click', () => {
        localStorage.removeItem(AUTH_KEY);
        location.reload();
      });
    }
  };

  const bindCreate = () => {
    const form = $('#create-form');
    if (!form) return;
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const get = (name) => form.querySelector(`[name="${name}"]`);
      const type = (get('type')?.value || '').trim();
      const name = (get('name')?.value || '').trim();
      const department = (get('department')?.value || '').trim();
      const status = (get('status')?.value || '').trim();
      const amount = Number(get('amount')?.value || 0);
      const dueInDays = Number(get('dueInDays')?.value || 0);

      if (!name) return;

      api.create({ type, name, department, status, amount, dueInDays });
      form.reset();
      renderKpis();
      renderList();
    });
  };

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedEntities();
    bindAuth();
    bindCreate();

    const auth = readJSON(AUTH_KEY, null);
    if (auth && auth.email) showApp();
    else showLogin();

    renderKpis();
    renderList();
  });
})();

from fastapi import FastAPI, HTTPException, Header, Depends
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field
from typing import Optional, Any, Dict, List
from uuid import uuid4
from datetime import datetime, timezone

app = FastAPI(title="HR Onboarding Portal API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_EMAIL = "demo@example.com"
DEMO_PASSWORD = "demo"

# In-memory stores for now; a real database would be wired in here.
tokens: Dict[str, Dict[str, Any]] = {}
entities: Dict[str, Dict[str, Any]] = {}


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class LoginReq(BaseModel):
    email: EmailStr
    password: str


class User(BaseModel):
    id: str
    email: EmailStr
    name: str


class LoginRes(BaseModel):
    token: str
    user: User


class EntityBase(BaseModel):
    title: str = ""
    amount: float = 0
    description: Optional[str] = None


class Entity(EntityBase):
    id: str
    createdAt: str


class EntityCreate(EntityBase):
    pass


def get_current_user(authorization: Optional[str] = Header(default=None)) -> User:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Unauthorized")
    token = authorization.removeprefix("Bearer ").strip()
    payload = tokens.get(token)
    if not payload:
        raise HTTPException(status_code=401, detail="Unauthorized")
    return User(**payload["user"])


@app.post("/api/auth/login", response_model=LoginRes)
def login(req: LoginReq):
    if req.email != DEMO_EMAIL or req.password != DEMO_PASSWORD:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = uuid4().hex
    user = User(id="demo-user", email=DEMO_EMAIL, name="Demo User")
    tokens[token] = {"user": user.model_dump()}
    return LoginRes(token=token, user=user)


@app.get("/api/auth/me", response_model=User)
def me(user: User = Depends(get_current_user)):
    return user


@app.get("/api/entities", response_model=List[Entity])
def list_entities(user: User = Depends(get_current_user)):
    return list(entities.values())


@app.post("/api/entities", response_model=Entity)
def create_entity(entity: EntityCreate, user: User = Depends(get_current_user)):
    entity_id = uuid4().hex
    stored = Entity(
        id=entity_id,
        createdAt=now_iso(),
        title=entity.title,
        amount=entity.amount,
        description=entity.description,
    )
    entities[entity_id] = stored.model_dump()
    return stored


@app.delete("/api/entities/{entity_id}")
def delete_entity(entity_id: str, user: User = Depends(get_current_user)):
    if entity_id not in entities:
        raise HTTPException(status_code=404, detail="Entity not found")
    del entities[entity_id]
    return {"ok": True}


@app.get("/api/health")
def health():
