(() => {
  const AUTH_KEY = 'app:auth';
  const ENTITIES_KEY = 'app:entities';

  const $ = (sel) => document.querySelector(sel);

  const api = {
    list() {
      try {
        return JSON.parse(localStorage.getItem(ENTITIES_KEY) || '[]');
      } catch {
        return [];
      }
    },
    save(arr) {
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(arr));
    },
    create(obj) {
      const arr = api.list();
      const entity = {
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        ...obj
      };
      arr.push(entity);
      api.save(arr);
      return entity;
    },
    remove(id) {
      const arr = api.list().filter((item) => item.id !== id);
      api.save(arr);
    }
  };

  const seedEntities = () => {
    const existing = api.list();
    if (existing.length) return;

    const seed = [
      {
        kind: 'quote',
        client: 'Northwind Studio',
        number: 'Q-1001',
        status: 'Approved',
        amount: 1850,
        taxRate: 10,
        dueDate: '2026-02-15'
      },
      {
        kind: 'invoice',
        client: 'Acme Consulting',
        number: 'INV-2001',
        status: 'Paid',
        amount: 4200,
        taxRate: 8,
        dueDate: '2026-01-30'
      },
      {
        kind: 'invoice',
        client: 'Bright Side Media',
        number: 'INV-2002',
        status: 'Overdue',
        amount: 975,
        taxRate: 0,
        dueDate: '2026-01-10'
      },
      {
        kind: 'quote',
        client: 'Pixel Forge',
        number: 'Q-1002',
        status: 'Draft',
        amount: 625,
        taxRate: 5,
        dueDate: '2026-02-28'
      }
    ];

    localStorage.setItem(ENTITIES_KEY, JSON.stringify(seed));
  };

  const getAuth = () => {
    try {
      return JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
    } catch {
      return null;
    }
  };

  const setView = (loggedIn) => {
    const loginView = $('#login-view');
    const appView = $('#app-view');
    if (!loginView || !appView) return;
    loginView.style.display = loggedIn ? 'none' : '';
    appView.style.display = loggedIn ? '' : 'none';
  };

  const showLoginError = (msg) => {
    const el = $('#login-error');
    if (el) el.textContent = msg || '';
  };

  const money = (n) =>
    new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' }).format(Number(n || 0));

  const getFormValue = (name) => {
    const input = document.querySelector(`[name="${name}"]`);
    return input ? input.value.trim() : '';
  };

  const renderList = () => {
    const container = $('#entity-list');
    if (!container) return;
    const entities = api.list();

    if (!entities.length) {
      container.innerHTML = '<p>No quotes or invoices yet.</p>';
      return;
    }

    const rows = entities
      .map(
        (e) => `
          <tr>
            <td>${e.kind || 'invoice'}</td>
            <td>${e.number || ''}</td>
            <td>${e.client || ''}</td>
            <td>${e.status || ''}</td>
            <td>${money(e.amount)}</td>
            <td>${Number(e.taxRate || 0)}%</td>
            <td>${e.dueDate || ''}</td>
            <td><button type="button" data-remove-id="${e.id}">Delete</button></td>
          </tr>`
      )
      .join('');

    container.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Type</th>
            <th>#</th>
            <th>Client</th>
            <th>Status</th>
            <th>Amount</th>
            <th>Tax</th>
            <th>Due</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  };

  const renderKpis = () => {
    const strip = $('#kpi-strip');
    if (!strip) return;
    const entities = api.list();

    const count = entities.length;
    const totalAmount = entities.reduce((sum, e) => sum + Number(e.amount || 0), 0);
    const paidCount = entities.filter((e) => e.status === 'Paid').length;
    const overdueCount = entities.filter((e) => e.status === 'Overdue').length;

    strip.innerHTML = `
      <div class="kpi">Documents <strong>${count}</strong></div>
      <div class="kpi">Total Value <strong>${money(totalAmount)}</strong></div>
      <div class="kpi">Paid <strong>${paidCount}</strong></div>
      <div class="kpi">Overdue <strong>${overdueCount}</strong></div>
    `;
  };

  const refresh = () => {
    renderList();
    renderKpis();
  };

  const handleLogin = () => {
    const email = ($('#login-email') && $('#login-email').value.trim()) || '';
    const password = ($('#login-password') && $('#login-password').value) || '';

    if (email === 'demo@example.com' && password === 'demo') {
      localStorage.setItem(AUTH_KEY, JSON.stringify({ email, loggedAt: new Date().toISOString() }));
      showLoginError('');
      setView(true);
      refresh();
      return;
    }

    showLoginError('Invalid demo credentials. Try demo@example.com / demo');
  };

  const bindEvents = () => {
    const loginBtn = $('#login-btn');
    if (loginBtn) loginBtn.addEventListener('click', handleLogin);

    const logoutBtn = $('#logout-btn');
    if (logoutBtn) {
      logoutBtn.addEventListener('click', () => {
        localStorage.removeItem(AUTH_KEY);
        location.reload();
      });
    }

    const form = $('#create-form');
    if (form) {
      form.addEventListener('submit', (e) => {
        e.preventDefault();

        const data = {
          kind: getFormValue('kind') || 'invoice',
          client: getFormValue('client'),
          number: getFormValue('number'),
          status: getFormValue('status') || 'Draft',
          amount: Number(getFormValue('amount') || 0),
          taxRate: Number(getFormValue('taxRate') || 0),
          dueDate: getFormValue('dueDate')
        };

        if (!data.client || !data.number) return;

        api.create(data);
        form.reset();
        refresh();
      });
    }

    const list = $('#entity-list');
    if (list) {
      list.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-remove-id]');
        if (!btn) return;
        api.remove(btn.getAttribute('data-remove-id'));
        refresh();
      });
    }
  };

  document.addEventListener('DOMContentLoaded', () => {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedEntities();

    const loggedIn = !!getAuth();
    setView(loggedIn);
    bindEvents();
    if (loggedIn) refresh();
  });
})();

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Dict, List, Optional
from uuid import uuid4

from fastapi import FastAPI, Header, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, ConfigDict, EmailStr, Field

app = FastAPI(title="Invoice & Quote Generator API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_USER = {
    "id": "demo-user",
    "email": "demo@example.com",
    "name": "Demo User",
}

TOKENS: Dict[str, Dict[str, str]] = {}
ENTITIES: Dict[str, Dict[str, Any]] = {}
# In production, swap the in-memory stores above for a persistent database
# (e.g. Postgres + an ORM/repository layer).


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class UserOut(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    email: str
    name: str


class LoginReq(BaseModel):
    email: EmailStr
    password: str = Field(min_length=1)


class LoginResp(BaseModel):
    token: str
    user: UserOut


class EntityIn(BaseModel):
    title: str
    amount: float
    model_config = ConfigDict(extra="allow")


class EntityOut(BaseModel):
    model_config = ConfigDict(from_attributes=True, extra="allow")

    id: str
    createdAt: str
    title: str
    amount: float


class HealthOut(BaseModel):
    status: str
    version: str


def auth_user(authorization: Optional[str]) -> Dict[str, str]:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    token = authorization.removeprefix("Bearer ").strip()
    user = TOKENS.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    return user


@app.post("/api/auth/login", response_model=LoginResp)
def login(req: LoginReq) -> LoginResp:
    if req.email != DEMO_USER["email"] or req.password != "demo":
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")
    token = uuid4().hex
    TOKENS[token] = DEMO_USER
    return LoginResp(token=token, user=UserOut(**DEMO_USER))


@app.get("/api/auth/me", response_model=UserOut)
def me(authorization: Optional[str] = Header(default=None)) -> UserOut:
    user = auth_user(authorization)
    return UserOut(**user)


@app.get("/api/entities", response_model=List[EntityOut])
def list_entities(authorization: Optional[str] = Header(default=None)) -> List[EntityOut]:
    auth_user(authorization)
    return [EntityOut(**entity) for entity in ENTITIES.values()]


@app.post("/api/entities", response_model=EntityOut, status_code=status.HTTP_201_CREATED)
def create_entity(
    entity: EntityIn,
    authorization: Optional[str] = Header(default=None),
) -> EntityOut:
    auth_user(authorization)
    entity_id = uuid4().hex
    stored = {
        "id": entity_id,
        "createdAt": now_iso(),
        **entity.model_dump(),
    }
    ENTITIES[entity_id] = stored
    return EntityOut(**stored)


@app.delete("/api/entities")
def delete_entity(
    id: str,
    authorization: Optional[str] = Header(default=None),
) -> Dict[str, bool]:
    auth_user(authorization)
    if id not in ENTITIES:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del ENTITIES[id]
    return {"ok": True}


@app.get("/api/health", response_model=HealthOut)
def health() -> HealthOut:
    return HealthOut(status="ok", version=app.version or "1.0.0")

