    el.textContent = message || '';
  }

  function formatMoney(amount) {
    const n = Number(amount || 0);
    return n.toLocaleString(undefined, { style: 'currency', currency: 'USD' });
  }

  function formatDate(value) {
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return '—';
    return d.toLocaleString();
  }

  function renderKpis() {
    const entities = api.list();
    const total = entities.length;
    const revenue = entities.reduce((sum, item) => sum + Number(item.amount || 0), 0);
    const confirmed = entities.filter((item) => item.status === 'confirmed').length;
    const pending = entities.filter((item) => item.status === 'pending').length;
    const bookedToday = entities.filter((item) => {
      const d = new Date(item.slot || item.createdAt);
      const now = new Date();
      return d.toDateString() === now.toDateString();
    }).length;

    const strip = qs('#kpi-strip');
    if (!strip) return;

    strip.innerHTML = `
      <div class="kpi"><strong>${total}</strong><span>Bookings</span></div>
      <div class="kpi"><strong>${formatMoney(revenue)}</strong><span>Gross sales</span></div>
      <div class="kpi"><strong>${confirmed}</strong><span>Confirmed</span></div>
      <div class="kpi"><strong>${pending}</strong><span>Pending</span></div>
      <div class="kpi"><strong>${bookedToday}</strong><span>Today</span></div>
    `;
  }

  function renderList() {
    const list = api.list();
    const container = qs('#entity-list');
    if (!container) return;

    if (!list.length) {
      container.innerHTML = '<p>No bookings yet.</p>';
      return;
    }

    const rows = list
      .map(
        (item) => `
        <tr>
          <td>${escapeHtml(item.location || '')}</td>
          <td>${escapeHtml(item.service || '')}</td>
          <td>${escapeHtml(item.customer || '')}</td>
          <td>${formatDate(item.slot || item.createdAt)}</td>
          <td>${formatMoney(item.amount)}</td>
          <td>${escapeHtml(item.status || '')}</td>
          <td><button type="button" class="delete-btn" data-id="${item.id}">Delete</button></td>
        </tr>`
      )
      .join('');

    container.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Location</th>
            <th>Service</th>
            <th>Customer</th>
            <th>Slot</th>
            <th>Amount</th>
            <th>Status</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  }

  function escapeHtml(value) {
    return String(value)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function renderAll() {
    renderList();
    renderKpis();
  }

  function bindAuth() {
    const loginBtn = qs('#login-btn');
    const emailInput = qs('#login-email');
    const passInput = qs('#login-password');

    if (!loginBtn) return;

    loginBtn.addEventListener('click', () => {
      setLoginError('');
      const email = (emailInput && emailInput.value.trim()) || '';
      const password = (passInput && passInput.value) || '';

      if (email === demoCreds.email && password === demoCreds.password) {
        writeJSON(AUTH_KEY, { email, loggedAt: new Date().toISOString() });
        showApp(true);
        renderAll();
      } else {
        setLoginError('Invalid demo credentials. Try demo@example.com / demo');
      }
    });

    const form = loginBtn.closest('form');
    if (form) {
      form.addEventListener('submit', (e) => {
        e.preventDefault();
        loginBtn.click();
      });
    }
  }

  function bindLogout() {
    const logoutBtn = qs('#logout-btn');
    if (!logoutBtn) return;
    logoutBtn.addEventListener('click', () => {
      localStorage.removeItem(AUTH_KEY);
      location.reload();
    });
  }

  function bindCreateForm() {
    const form = qs('#create-form');
    if (!form) return;

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const fd = new FormData(form);

      const entity = {
        location: String(fd.get('location') || '').trim(),
        service: String(fd.get('service') || '').trim(),
        customer: String(fd.get('customer') || '').trim(),
        amount: Number(fd.get('amount') || 0),
        status: String(fd.get('status') || 'pending').trim(),
        slot: String(fd.get('slot') || new Date().toISOString())
      };

      if (!entity.location || !entity.service || !entity.customer) return;

      api.create(entity);
      form.reset();
      renderAll();
    });
  }

  function bindListActions() {
    const container = qs('#entity-list');
    if (!container) return;
    container.addEventListener('click', (e) => {
      const btn = e.target.closest('.delete-btn');
      if (!btn) return;
      const id = btn.getAttribute('data-id');
      if (!id) return;
      api.remove(id);
      renderAll();
    });
  }

  function init() {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedEntitiesIfEmpty();

    const auth = readJSON(AUTH_KEY, null);
    showApp(Boolean(auth && auth.email));

    bindAuth();
    bindLogout();
    bindCreateForm();
    bindListActions();

    if (auth && auth.email) {
      renderAll();
    } else {
      setLoginError('');
    }
  }

  document.addEventListener('DOMContentLoaded', init);
})();

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Dict, List, Optional
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, ConfigDict, EmailStr, Field

APP_VERSION = "1.0.0"

app = FastAPI(title="BookNest API", version=APP_VERSION)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# In-memory demo storage. In production, this would be replaced by a real DB layer
# (e.g. PostgreSQL via SQLAlchemy/SQLModel, with proper persistence and indexing).
entities_by_id: Dict[str, Dict[str, Any]] = {}
sessions_by_token: Dict[str, Dict[str, Any]] = {}

demo_user = {
    "id": "demo-user",
    "email": "demo@example.com",
    "name": "Demo User",
    "role": "owner",
}


class LoginReq(BaseModel):
    email: str
    password: str


class User(BaseModel):
    model_config = ConfigDict(extra="ignore")

    id: str
    email: EmailStr
    name: str
    role: str


class LoginRes(BaseModel):
    token: str
    user: User


class EntityIn(BaseModel):
    title: str = Field(min_length=1)
    amount: float = 0


class EntityOut(EntityIn):
    id: str
    createdAt: str


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def auth_user(request: Request) -> Dict[str, Any]:
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    token = auth.removeprefix("Bearer ").strip()
    user = sessions_by_token.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    return user


@app.get("/api/health")
def health() -> Dict[str, str]:
    return {"status": "ok", "version": APP_VERSION}


@app.post("/api/auth/login", response_model=LoginRes)
def login(payload: LoginReq) -> LoginRes:
    if payload.email != "demo@example.com" or payload.password != "demo":
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")

    token = uuid4().hex
    sessions_by_token[token] = demo_user
    return LoginRes(token=token, user=User(**demo_user))


@app.get("/api/auth/me", response_model=User)
def me(request: Request) -> User:
    user = auth_user(request)
    return User(**user)


@app.get("/api/entities", response_model=List[EntityOut])
def list_entities(request: Request) -> List[EntityOut]:
    auth_user(request)
    return [EntityOut(**entity) for entity in entities_by_id.values()]


@app.post("/api/entities", response_model=EntityOut, status_code=status.HTTP_201_CREATED)
def create_entity(payload: EntityIn, request: Request) -> EntityOut:
    auth_user(request)
    entity_id = uuid4().hex
    entity = {
        "id": entity_id,
        "createdAt": now_iso(),
        "title": payload.title,
        "amount": payload.amount,
    }
    entities_by_id[entity_id] = entity
    return EntityOut(**entity)


@app.delete("/api/entities")
def delete_entity(request: Request, id: str) -> Dict[str, bool]:
    auth_user(request)
    if id not in entities_by_id:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del entities_by_id[id]
    return {"ok": True}

