      <div class="kpi"><strong>${active}</strong><span>Active listings</span></div>
      <div class="kpi"><strong>${scheduled}</strong><span>Scheduled showings</span></div>
      <div class="kpi"><strong>${negotiating}</strong><span>Negotiations</span></div>
      <div class="kpi"><strong>$${pipelineValue.toLocaleString()}</strong><span>Pipeline value</span></div>
    `;
  }

  function renderList() {
    const host = $("#entity-list");
    if (!host) return;
    const items = api.list();

    if (!items.length) {
      host.innerHTML = "<p>No pipeline items yet.</p>";
      return;
    }

    const rows = items
      .slice()
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
      .map(
        (x) => `
        <tr>
          <td>${escapeHtml(x.type || "")}</td>
          <td>${escapeHtml(x.title || "")}</td>
